-- Analytical View: Mutation Frequency---- Purpose:-- Summarize the observed frequency of selected mutations-- within each histological subtype.---- Grain:-- One row per histological subtype and gene.---- Source:-- analytical.vw_mutation_by_histologyCREATE OR REPLACE VIEW analytical.vw_mutation_frequency ASSELECT    histological_type,    gene,    SUM(        CASE            WHEN mutation_status = 1 THEN 1            ELSE 0        END    ) AS mutated_samples,    COUNT(*) AS total_samples,    ROUND(        100.0 * SUM(            CASE                WHEN mutation_status = 1 THEN 1                ELSE 0            END        ) / COUNT(*),        2    ) AS mutation_frequency_pctFROM analytical.vw_mutation_by_histologyGROUP BY    histological_type,    gene;